/* A bare checkbox in a settings row is drawn as the same switch as the rest. */
.setting-row input[type="checkbox"] {
  appearance: none; position: relative; flex: none; width: 40px; height: 24px; border-radius: 12px; cursor: pointer;
  background: var(--sunk); border: 1px solid var(--line-strong); transition: background var(--base), border-color var(--base);
}
.setting-row input[type="checkbox"]::after {
  content: ''; position: absolute; left: 3px; top: 3px; width: 16px; height: 16px; border-radius: 50%;
  background: var(--mute); transition: transform var(--base) var(--ease), background var(--base), box-shadow var(--base);
}
.setting-row input[type="checkbox"]:checked { background: color-mix(in srgb, var(--accent) 32%, var(--sunk)); border-color: var(--accent-line); }
.setting-row input[type="checkbox"]:checked::after { transform: translateX(16px); background: var(--accent); box-shadow: 0 0 10px var(--accent); }
